package io.github.diodeme.ji.agent;

import java.time.Instant;
import java.util.Map;
import java.util.concurrent.CompletionStage;

/** Shared permission decision port used by every inbound adapter. */
@FunctionalInterface
public interface PermissionDecider {
    CompletionStage<Decision> decide(Request request);

    record Request(
            String permissionId,
            String sessionId,
            String toolCallId,
            String toolName,
            Map<String, Object> arguments,
            long revision,
            Instant expiresAt) {
        public Request {
            if (permissionId == null || permissionId.isBlank()) throw new IllegalArgumentException("permissionId must not be blank");
            if (sessionId == null || sessionId.isBlank()) throw new IllegalArgumentException("sessionId must not be blank");
            if (toolCallId == null || toolCallId.isBlank()) throw new IllegalArgumentException("toolCallId must not be blank");
            if (toolName == null || toolName.isBlank()) throw new IllegalArgumentException("toolName must not be blank");
            arguments = Map.copyOf(arguments);
            if (revision < 0) throw new IllegalArgumentException("revision must be non-negative");
            if (expiresAt == null) throw new IllegalArgumentException("expiresAt must not be null");
        }
    }

    enum Decision { ALLOW, DENY }
}
